function alphaFor(k) {
  if (k.branch && state.branch !== 'both' && k.branch !== state.branch) return 0;
  const step = state.layer;
  const active = Math.min(step, 4);
  let a = 1;
  if (k.type === 'plane' || k.type === 'marker' || k.type === 'token') a *= (k.layer <= active) ? 1 : 0.16;
  if (k.type === 'path') a *= (k.seg < step) ? 0.5 : 0.05;
  if (k.type === 'arrow' || k.type === 'block') a *= (k.index < step) ? 1 : 0.25;
  if (k.type === 'joint' || k.type === 'jointArrow') a *= (step >= 5) ? 1 : 0.18;
  if (state.highlight && k.concept) {
    if (k.concept === state.highlight) {
      if (k.type === 'path') a = (k.seg < step) ? 1 : 0.1;
      else a = Math.max(a, 1);
    } else {
      a *= 0.12;
    }
  }
  return a;
}

function markerTargetScale(rec) {
  let s = 0.34;
  if (state.highlight === rec.concept) s *= 1.5;
  if (rec.layer === Math.min(state.layer, 4)) s *= (1 + 0.45 * pulse);
  return s;
}

function refresh() {
  for (const f of fades) f.tgt = alphaFor(f.key);
  for (const t of tokenRecs) {
    const hi = state.highlight === t.concept;
    t.div.style.fontSize = hi ? '13px' : '9px';
    t.div.style.fontWeight = hi ? '700' : '400';
  }
  document.querySelectorAll('#layerRow .lbtn').forEach(b => b.classList.toggle('active', +b.dataset.i === state.layer));
  document.querySelectorAll('#branchRow .bbtn').forEach(b => b.classList.toggle('active', b.dataset.b === state.branch));
}

function tickFades() {
  requestAnimationFrame(tickFades);
  if (pulse > 0) { pulse *= 0.94; if (pulse < 0.01) pulse = 0; }
  for (const f of fades) {
    if (Math.abs(f.cur - f.tgt) > 0.003) { f.cur += (f.tgt - f.cur) * 0.14; f.apply(f.cur); }
    else if (f.cur !== f.tgt) { f.cur = f.tgt; f.apply(f.cur); }
  }
  for (const m of markerRecs) {
    const t = markerTargetScale(m);
    const c = m.sprite.scale.x + (t - m.sprite.scale.x) * 0.2;
    m.sprite.scale.set(c, c, 1);
  }
}
tickFades();

/* ── controls ─────────────────────────────────────────────────────────────── */
const sel = document.getElementById('conceptSel');
CONCEPTS.forEach(c => {
  const o = document.createElement('option'); o.value = c.id; o.textContent = c.id; sel.appendChild(o);
});
sel.addEventListener('change', () => { state.highlight = sel.value || null; refresh(); });

document.getElementById('layerRow').addEventListener('click', e => {
  const b = e.target.closest('button'); if (!b) return;
  if (+b.dataset.i !== state.layer) pulse = 1;
  state.layer = +b.dataset.i; stopPlay(); refresh();
});
document.getElementById('branchRow').addEventListener('click', e => {
  const b = e.target.closest('button'); if (!b) return;
