  if (sel.value) return;
  const r = renderer.domElement.getBoundingClientRect();
  ndc.x = ((e.clientX - r.left) / r.width) * 2 - 1;
  ndc.y = -((e.clientY - r.top) / r.height) * 2 + 1;
  rc.setFromCamera(ndc, camera);
  const hits = rc.intersectObjects(pickTargets, false);
  const id = hits.length ? hits[0].object.userData.concept : null;
  if (id !== state.highlight) { state.highlight = id; refresh(); }
});
renderer.domElement.addEventListener('pointerleave', () => {
  if (sel.value) return;
  if (state.highlight) { state.highlight = null; refresh(); }
});

/* ── guided demo ──────────────────────────────────────────────────────────── */
const STEPS = [
  { title: 'Raw inputs', text: 'At the bottom plane the image markers and the text strings sit in unrelated arrangements — pixels and tokens have nothing in common yet.', layer: 0, branch: 'both' },
  { title: 'Image branch alone', text: 'Hiding text, follow the colored markers upward: each ViT block x3 nudges the shapes into clusters by colour and form.', layer: 2, branch: 'image' },
  { title: 'Text branch alone', text: 'The transformer blocks do the same job on strings like “blue triangle” — a purely within-modality reorganization.', layer: 2, branch: 'text' },
  { title: 'Layouts converge', text: 'With both branches back, the top planes show markers and captions in matching relative positions: the encoders have been trained toward a common geometry.', layer: 4, branch: 'both' },
  { title: 'Joint embedding space', text: 'Both final planes project into one orange disk, where an image vector and its caption vector can finally be compared by cosine similarity.', layer: 5, branch: 'both' }
];
let stepIdx = 0, playTimer = null;
const narr = document.getElementById('narration');
function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  if (s.layer !== state.layer) pulse = 1;
  state.layer = s.layer; state.branch = s.branch;
  narr.innerHTML = '<b>' + s.title + '</b><br>' + s.text;
  refresh();
}
function stopPlay() {
  if (playTimer) { clearInterval(playTimer); playTimer = null; document.getElementById('playDemo').textContent = '▶ Play'; }
}
document.getElementById('nextStep').addEventListener('click', () => { stopPlay(); goToStep(stepIdx + 1); });
document.getElementById('prevStep').addEventListener('click', () => { stopPlay(); goToStep(stepIdx - 1); });
document.getElementById('playDemo').addEventListener('click', () => {
  if (playTimer) { stopPlay(); return; }
  document.getElementById('playDemo').textContent = '❚❚ Pause';
  goToStep(0);
  playTimer = setInterval(() => {
    if (stepIdx >= STEPS.length - 1) { stopPlay(); return; }
    goToStep(stepIdx + 1);
  }, 3800);
});

refresh();
