const T = [0, 0.28, 0.55, 0.80, 1.0];

const CONCEPTS = [
  { id: 'red circle',      color: 0xEF6A6A, shape: 'circle' },
  { id: 'orange circle',   color: 0xF5B267, shape: 'circle' },
  { id: 'pink circle',     color: 0xF48FB1, shape: 'circle' },
  { id: 'purple circle',   color: 0xB39DDB, shape: 'circle' },
  { id: 'blue circle',     color: 0x64B5F6, shape: 'circle' },
  { id: 'pink square',     color: 0xF06BB4, shape: 'square' },
  { id: 'blue square',     color: 0x7EC8E3, shape: 'square' },
  { id: 'green square',    color: 0x66BB6A, shape: 'square' },
  { id: 'blue triangle',   color: 0x4FA8D8, shape: 'triangle' },
  { id: 'purple triangle', color: 0xA48AD0, shape: 'triangle' }
];

function mulberry(seed) {
  return function () {
    seed |= 0; seed = seed + 0x6D2B79F5 | 0;
    let t = Math.imul(seed ^ seed >>> 15, 1 | seed);
    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
}

const CLUSTER = { circle: { x: -1.05, z: -0.55 }, square: { x: 0.05, z: -1.25 }, triangle: { x: 1.15, z: 0.45 } };
const rf = mulberry(99);
const FINAL = CONCEPTS.map(c => {
  const cc = CLUSTER[c.shape];
  return { x: cc.x + (rf() * 2 - 1) * 0.32, z: cc.z + (rf() * 2 - 1) * 0.32 };
});

function branchPositions(seed, spreadText) {
  const rnd = mulberry(seed);
  const start = CONCEPTS.map(() => ({ x: (rnd() * 2 - 1) * 1.7, z: (rnd() * 2 - 1) * 1.7 }));
  const jit = CONCEPTS.map(() => T.map(() => ({ x: rnd() * 2 - 1, z: rnd() * 2 - 1 })));
  return CONCEPTS.map((c, i) => T.map((t, l) => {
    let x = start[i].x + (FINAL[i].x - start[i].x) * t + jit[i][l].x * 0.45 * (1 - t);
    let z = start[i].z + (FINAL[i].z - start[i].z) * t + jit[i][l].z * 0.45 * (1 - t);
    if (spreadText) { x *= 1.3; z *= 1.22; }   // captions fan out past the plane corners
    return { x, z };
  }));
}
const POS = { image: branchPositions(7, false), text: branchPositions(23, true) };

/* ── fade bookkeeping ─────────────────────────────────────────────────────── */
const fades = [];
function addFade(key, apply) { const e = { key, apply, cur: 1, tgt: 1 }; fades.push(e); return e; }
function matFade(key, mat, base = 1) {
  mat.transparent = true;
  return addFade(key, a => { mat.opacity = base * a; mat.visible = a > 0.012; });
}
function divFade(key, div) { return addFade(key, a => { div.style.opacity = a; div.style.visibility = a > 0.02 ? 'visible' : 'hidden'; }); }

/* ── helpers ──────────────────────────────────────────────────────────────── */
function shade(hex, f) { const c = new THREE.Color(hex); c.offsetHSL(0, 0, f); return '#' + c.getHexString(); }

function glyphTexture(shape, hex) {
  const S = 128, cv = document.createElement('canvas'); cv.width = cv.height = S;
  const x = cv.getContext('2d');
  x.fillStyle = '#' + hex.toString(16).padStart(6, '0');
  x.strokeStyle = shade(hex, -0.22); x.lineWidth = 10; x.lineJoin = 'round';
  const m = 20, a = S - m;
  if (shape === 'circle') { x.beginPath(); x.arc(S / 2, S / 2, (S - 2 * m) / 2, 0, Math.PI * 2); x.fill(); x.stroke(); }
  else if (shape === 'square') { x.beginPath(); x.rect(m, m, S - 2 * m, S - 2 * m); x.fill(); x.stroke(); }
  else { x.beginPath(); x.moveTo(S / 2, m); x.lineTo(a, a - 6); x.lineTo(m, a - 6); x.closePath(); x.fill(); x.stroke(); }
  const t = new THREE.CanvasTexture(cv);
  if (THREE.SRGBColorSpace) t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

function makeArrow(from, to, r = 0.055, headR = 0.17, headL = 0.44) {
  const g = new THREE.Group();
  const dir = new THREE.Vector3().subVectors(to, from);
  const len = dir.length(); dir.normalize();
  const shaftLen = Math.max(0.02, len - headL);
  const mat = new THREE.MeshBasicMaterial({ color: 0x000000, transparent: true });
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(r, r, shaftLen, 12), mat);
  shaft.position.y = shaftLen / 2;
  const head = new THREE.Mesh(new THREE.ConeGeometry(headR, headL, 18), mat);
  head.position.y = shaftLen + headL / 2;
  g.add(shaft); g.add(head);
  g.position.copy(from);
  g.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  scene.add(g);
  return mat;
}

/* ── build the two branches ───────────────────────────────────────────────── */
const tokenSpecs = [];
const markerRecs = [];
const tokenRecs = [];
const pickTargets = [];
const BRANCHES = [
  { name: 'image', s: -4.5, rail: -10.5, blockX: -7.6, block: 'ViT block x3', rule: 'Image encoder' },
  { name: 'text', s: 4.5, rail: 10.5, blockX: 7.6, block: 'transformer block x3', rule: 'Text encoder' }
];
const blockSpecs = [];
const ruleSpecs = [];

const glyphTex = {};
CONCEPTS.forEach(c => { glyphTex[c.id] = glyphTexture(c.shape, c.color); });

// centre of plane `l` for branch B, including the zig-zag lateral offset
function planeCenter(B, l) { return P(B.s + ZIG[l], LY[l]); }

BRANCHES.forEach(B => {
  // planes
  for (let l = 0; l < 5; l++) {
    const g = new THREE.Group();
    g.position.copy(planeCenter(B, l));
    const grid = new THREE.GridHelper(4, 4, 0xe2e2e2, 0xe2e2e2);
    grid.material.transparent = true;
    matFade({ type: 'plane', branch: B.name, layer: l }, grid.material, 1);
    g.add(grid);
    const pts = [new THREE.Vector3(-2, 0, -2), new THREE.Vector3(2, 0, -2), new THREE.Vector3(2, 0, 2),
    new THREE.Vector3(-2, 0, 2), new THREE.Vector3(-2, 0, -2)];
    const om = new THREE.LineBasicMaterial({ color: 0x4a4a4a, transparent: true });
    matFade({ type: 'plane', branch: B.name, layer: l }, om, 1);
    g.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), om));
    scene.add(g);
  }

  // markers / tokens + pick proxies
  CONCEPTS.forEach((c, ci) => {
    for (let l = 0; l < 5; l++) {
      const p = POS[B.name][ci][l];
      const wp = planeCenter(B, l).add(new THREE.Vector3(p.x, 0.03, p.z));
      if (B.name === 'image') {
        const mat = new THREE.SpriteMaterial({ map: glyphTex[c.id], transparent: true, depthTest: false, depthWrite: false });
        const sp = new THREE.Sprite(mat);
        sp.position.copy(wp); sp.scale.set(0.34, 0.34, 1);
        scene.add(sp);
        matFade({ type: 'marker', branch: 'image', layer: l, concept: c.id }, mat, 1);
        markerRecs.push({ sprite: sp, concept: c.id, layer: l });
      } else {
        // fan captions around the plane's perimeter instead of stacking them on one side
        const ang = (ci / CONCEPTS.length) * Math.PI * 2 + l * 0.55;
        tokenSpecs.push({
          text: c.id, pos: wp, concept: c.id, layer: l,
          offset: [Math.cos(ang) * 34, Math.sin(ang) * 17]
        });
      }
      const proxy = new THREE.Mesh(new THREE.SphereGeometry(0.22, 8, 6),
        new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false }));
      proxy.position.copy(wp);
      proxy.userData.concept = c.id;
      scene.add(proxy);
      pickTargets.push(proxy);
      registerInteractive(proxy, {
        title: c.id + (B.name === 'image' ? ' (image branch)' : ' (text branch)'),
        tooltip: c.id + ' — trace this concept',
        body: 'Layer ' + l + ' of the ' + (B.name === 'image' ? 'image' : 'text') + ' encoder. ' +
          'The dashed path shows where this concept sits on each 2-D embedding slice; by the top plane the ' +
          'image marker and the text caption occupy matching relative positions, which is what makes the ' +
          'joint embedding space comparable.'
      });
    }

    // trajectories
    for (let s = 0; s < 4; s++) {
      const a = POS[B.name][ci][s], b = POS[B.name][ci][s + 1];
      const pa = planeCenter(B, s).add(new THREE.Vector3(a.x, 0.02, a.z));
      const pb = planeCenter(B, s + 1).add(new THREE.Vector3(b.x, 0.02, b.z));
      const mat = new THREE.LineDashedMaterial({
        color: B.name === 'image' ? c.color : 0x8a8a8a,
        dashSize: 0.12, gapSize: 0.12, transparent: true
      });
      const ln = new THREE.Line(new THREE.BufferGeometry().setFromPoints([pa, pb]), mat);
      ln.computeLineDistances();
      scene.add(ln);
      matFade({ type: 'path', branch: B.name, seg: s, concept: c.id }, mat, 1);
    }
  });

  // encoder arrows + block boxes
  for (let i = 0; i < 4; i++) {
    const y0 = LY[i] + 0.4;
    const m = makeArrow(P(B.blockX, y0), P(B.blockX, y0 + 1.8));
    addFade({ type: 'arrow', branch: B.name, index: i }, a => { m.opacity = a; m.visible = a > 0.012; });
    blockSpecs.push({ text: B.block, pos: P(B.blockX, y0 + 0.9), branch: B.name, index: i });
  }

  // vertical rule
  const rm = new THREE.LineBasicMaterial({ color: 0x000000, transparent: true });
  const rl = new THREE.Line(new THREE.BufferGeometry().setFromPoints([P(B.rail, -0.5), P(B.rail, 12)]), rm);
  scene.add(rl);
  matFade({ type: 'rule', branch: B.name }, rm, 1);
  ruleSpecs.push({ text: B.rule, pos: P(B.rail, 5.8), branch: B.name, dir: B.name === 'image' ? -90 : 90 });
});

/* ── joint embedding disk + two arrows ────────────────────────────────────── */
const diskG = new THREE.Group();
diskG.position.copy(P(0, 13.6));
const diskMat = new THREE.MeshBasicMaterial({ color: 0xF5A882, transparent: true, side: THREE.DoubleSide });
const disk = new THREE.Mesh(new THREE.CircleGeometry(1, 64), diskMat);
disk.onBeforeRender = (r, s, cam) => { diskG.quaternion.copy(cam.quaternion); };
const ringPts = [];
for (let i = 0; i <= 64; i++) { const a = i / 64 * Math.PI * 2; ringPts.push(new THREE.Vector3(Math.cos(a), Math.sin(a), 0.001)); }
const ringMat = new THREE.LineBasicMaterial({ color: 0x000000, transparent: true });
diskG.add(disk);
diskG.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(ringPts), ringMat));
scene.add(diskG);
matFade({ type: 'joint' }, diskMat, 1);
matFade({ type: 'joint' }, ringMat, 1);
registerInteractive(disk, {
  title: 'Joint embedding space',
  tooltip: 'Joint embedding space',
  body: 'Both encoders project their final 2-D slice into this single shared space. Only here can an image ' +
    'vector and a caption vector be compared directly (cosine similarity) — that comparison is what CLIP is trained on.'
});

const aL = makeArrow(P(-4.3, 11.15), P(-0.78, 12.92), 0.05, 0.19, 0.46);
addFade({ type: 'jointArrow', branch: 'image' }, a => { aL.opacity = a; aL.visible = a > 0.012; });
const aR = makeArrow(P(4.3, 11.15), P(0.78, 12.92), 0.05, 0.19, 0.46);
addFade({ type: 'jointArrow', branch: 'text' }, a => { aR.opacity = a; aR.visible = a > 0.012; });

// minimal invisible padding so the title label still has room above the disk
const padMat = new THREE.PointsMaterial({ size: 0.001, transparent: true, opacity: 0 });
padMat.visible = false;
scene.add(new THREE.Points(new THREE.BufferGeometry().setFromPoints([P(0, 15.0)]), padMat));

/* ── camera (after all geometry) ──────────────────────────────────────────── */
setCameraView({ projection: 'orthographic', axisScreenAngles: { x: 30, z: 30 }, heightFraction: 0.94 });
document.getElementById('btnReset').style.display = '';

/* ── labels ───────────────────────────────────────────────────────────────── */
for (const t of tokenSpecs) {
  const e = addLabel(t.text, t.pos, { fontSize: '11px', offset: t.offset });
  e.div.style.fontFamily = 'Georgia, "Times New Roman", serif';
  e.div.style.color = '#161616';
  divFade({ type: 'token', branch: 'text', layer: t.layer, concept: t.concept }, e.div);
  tokenRecs.push({ div: e.div, concept: t.concept });
}
for (const b of blockSpecs) {
  const e = addLabel(b.text, b.pos, { fontSize: '12px' });
  e.div.style.fontFamily = 'ui-monospace, Consolas, monospace';
  e.div.style.background = '#ffffff';
  e.div.style.border = '1px solid #111';
  e.div.style.borderRadius = '11px';
  e.div.style.padding = '3px 10px';
  divFade({ type: 'block', branch: b.branch, index: b.index }, e.div);
}
for (const r of ruleSpecs) {
  const e = addLabel('<span style="display:inline-block;transform:rotate(' + r.dir + 'deg)">' + r.text + '</span>', r.pos, { fontSize: '16px' });
  e.div.style.fontFamily = 'Georgia, "Times New Roman", serif';
  divFade({ type: 'rule', branch: r.branch }, e.div);
}
const titleLbl = addLabel('Joint embedding space', P(0, 15.1), { fontSize: '19px' });
titleLbl.div.style.fontFamily = 'Georgia, "Times New Roman", serif';

/* ── state + targets ──────────────────────────────────────────────────────── */
// default = the complete figure, exactly as printed in the source
const state = { layer: 5, branch: 'both', highlight: null };
let pulse = 0;

function alphaFor(k) {
  if (k.branch && state.branch !== 'both' && k.branch !== state.branch) return 0;
  const step = state.layer;
  const active = Math.min(step, 4);
  let a = 1;
  // nothing ever drops below a clearly readable floor: the whole diagram stays drawn
  if (k.type === 'plane' || k.type === 'marker' || k.type === 'token') a = (k.layer <= active) ? 1 : 0.55;
  if (k.type === 'path') a = (k.seg < step) ? 0.85 : 0.38;
  if (k.type === 'arrow' || k.type === 'block') a = (k.index < step) ? 1 : 0.6;
  // the orange disk and its two arrows are never dimmed below 0.75
  if (k.type === 'joint' || k.type === 'jointArrow') a = (step >= 5) ? 1 : 0.75;
  if (state.highlight && k.concept) {
    if (k.concept === state.highlight) a = 1;
    else a *= 0.14;
  }
  return a;
}

function markerTargetScale(rec) {
  let s = 0.34;
  if (state.highlight === rec.concept) s *= 1.5;
  if (rec.layer === Math.min(state.layer, 4)) s *= (1 + 0.45 * pulse);
  return s;
}

function refresh() {
  for (const f of fades) f.tgt = alphaFor(f.key);
  for (const t of tokenRecs) {
    const hi = state.highlight === t.concept;
    t.div.style.fontSize = hi ? '15px' : '11px';
    t.div.style.fontWeight = hi ? '700' : '400';
  }
  document.querySelectorAll('#layerRow .lbtn').forEach(b => b.classList.toggle('active', +b.dataset.i === state.layer));
  document.querySelectorAll('#branchRow .bbtn').forEach(b => b.classList.toggle('active', b.dataset.b === state.branch));
}

function tickFades() {
  requestAnimationFrame(tickFades);
  if (pulse > 0) { pulse *= 0.94; if (pulse < 0.01) pulse = 0; }
  for (const f of fades) {
    if (Math.abs(f.cur - f.tgt) > 0.003) { f.cur += (f.tgt - f.cur) * 0.14; f.apply(f.cur); }
    else if (f.cur !== f.tgt) { f.cur = f.tgt; f.apply(f.cur); }
  }
  for (const m of markerRecs) {
    const t = markerTargetScale(m);
    const c = m.sprite.scale.x + (t - m.sprite.scale.x) * 0.2;
    m.sprite.scale.set(c, c, 1);
  }
}
tickFades();

/* ── controls ─────────────────────────────────────────────────────────────── */
const sel = document.getElementById('conceptSel');
CONCEPTS.forEach(c => {
  const o = document.createElement('option'); o.value = c.id; o.textContent = c.id; sel.appendChild(o);
});
sel.addEventListener('change', () => { state.highlight = sel.value || null; refresh(); });

document.getElementById('layerRow').addEventListener('click', e => {
  const b = e.target.closest('button'); if (!b) return;
  if (+b.dataset.i !== state.layer) pulse = 1;
  state.layer = +b.dataset.i; stopPlay(); refresh();
});
document.getElementById('branchRow').addEventListener('click', e => {
  const b = e.target.closest('button'); if (!b) return;
  state.branch = b.dataset.b; stopPlay(); refresh();
});

/* hover picking */
const rc = new THREE.Raycaster();
const ndc = new THREE.Vector2();
renderer.domElement.addEventListener('pointermove', e => {
  if (sel.value) return;
  const r = renderer.domElement.getBoundingClientRect();
  ndc.x = ((e.clientX - r.left) / r.width) * 2 - 1;
  ndc.y = -((e.clientY - r.top) / r.height) * 2 + 1;
  rc.setFromCamera(ndc, camera);
  const hits = rc.intersectObjects(pickTargets, false);
  const id = hits.length ? hits[0].object.userData.concept : null;
  if (id !== state.highlight) { state.highlight = id; refresh(); }
});
renderer.domElement.addEventListener('pointerleave', () => {
  if (sel.value) return;
  if (state.highlight) { state.highlight = null; refresh(); }
});

/* ── guided demo ──────────────────────────────────────────────────────────── */
const STEPS = [
  { title: 'Raw inputs', text: 'At the bottom plane the image markers and the text strings sit in unrelated arrangements — pixels and tokens have nothing in common yet. Higher layers stay faintly drawn.', layer: 0, branch: 'both' },
  { title: 'Image branch alone', text: 'Hiding text, follow the colored markers upward: each ViT block x3 nudges the shapes into clusters by colour and form.', layer: 2, branch: 'image' },
  { title: 'Text branch alone', text: 'The transformer blocks do the same job on strings like “blue triangle” — a purely within-modality reorganization.', layer: 2, branch: 'text' },
  { title: 'Layouts converge', text: 'With both branches back, the top planes show markers and captions in matching relative positions: the encoders have been trained toward a common geometry.', layer: 4, branch: 'both' },
  { title: 'Joint embedding space', text: 'Both final planes project into one orange disk, where an image vector and its caption vector can finally be compared by cosine similarity.', layer: 5, branch: 'both' }
];
let stepIdx = 4, playTimer = null;
const narr = document.getElementById('narration');
function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  if (s.layer !== state.layer) pulse = 1;
  state.layer = s.layer; state.branch = s.branch;
  narr.innerHTML = '<b>' + s.title + '</b><br>' + s.text;
  refresh();
}
function stopPlay() {
  if (playTimer) { clearInterval(playTimer); playTimer = null; document.getElementById('playDemo').textContent = '▶ Play'; }
}
document.getElementById('nextStep').addEventListener('click', () => { stopPlay(); goToStep(stepIdx + 1); });
document.getElementById('prevStep').addEventListener('click', () => { stopPlay(); goToStep(stepIdx - 1); });
document.getElementById('playDemo').addEventListener('click', () => {
  if (playTimer) { stopPlay(); return; }
  document.getElementById('playDemo').textContent = '❚❚ Pause';
  goToStep(0);
  playTimer = setInterval(() => {
    if (stepIdx >= STEPS.length - 1) { stopPlay(); return; }
    goToStep(stepIdx + 1);
  }, 3800);
});

refresh();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

