// The diagonal layout makes the world AABB far taller on screen than the
// drawing actually is, so the scaffold's bounds auto-fit would shrink the
// figure. Screen-space extents are known analytically here, so fit from those.
const SCRX = RAIL_X + 0.8;                 // rules + their rotated labels
const SCR_MIN_Y = -2.1;                    // bottom plane far corner / rule foot
const SCR_MAX_Y = 13.2;                    // title above the disk
