    projection: 'orthographic', axisScreenAngles: { x: 30, z: 30 },
    heightFraction: 0.72, zoom: z, target: [t.x, t.y, t.z]
  });
}
fitView();
document.getElementById('btnReset').style.display = '';
new ResizeObserver(() => {
  const w = canvas.clientWidth, h = canvas.clientHeight;
  if (!w || !h || _userMovedCamera) return;
  aspect = w / h;
  fitView();
}).observe(canvas);

/* ── labels ───────────────────────────────────────────────────────────────── */
for (const t of tokenSpecs) {
  const e = addLabel(t.text, t.pos, { fontSize: '12px', offset: t.offset });
